fn reverse(a: &[char]) -> Vec<char> {
    // Preallocate a vector with the same length as the input slice.
    let mut b = Vec::with_capacity(a.len());
    // Iterate over `a` in reverse order, cloning each `char` into `b`.
    for &ch in a.iter().rev() {
        b.push(ch);
    }
    b
}

